import pytest
from semverrange import satisfies


class TestExactMatching:
    """Test exact version matching."""

    def test_exact_match_basic(self):
        assert satisfies("1.2.3", "1.2.3")

    def test_exact_match_zero_versions(self):
        assert satisfies("0.0.0", "0.0.0")

    def test_exact_mismatch(self):
        assert not satisfies("1.2.4", "1.2.3")

    def test_exact_with_leading_v_in_version(self):
        assert satisfies("v1.2.3", "1.2.3")

    def test_exact_with_leading_v_in_range(self):
        assert satisfies("1.2.3", "v1.2.3")

    def test_exact_with_leading_v_in_both(self):
        assert satisfies("v1.2.3", "v1.2.3")

    def test_exact_with_whitespace_in_version(self):
        assert satisfies("  1.2.3  ", "1.2.3")

    def test_exact_with_whitespace_in_range(self):
        assert satisfies("1.2.3", "  1.2.3  ")

    def test_exact_with_prerelease_match(self):
        assert satisfies("1.2.3-alpha", "1.2.3-alpha")

    def test_exact_with_prerelease_mismatch(self):
        assert not satisfies("1.2.3-alpha", "1.2.3-beta")

    def test_exact_with_prerelease_vs_release(self):
        assert not satisfies("1.2.3-alpha", "1.2.3")

    def test_exact_with_build_metadata_ignored(self):
        assert satisfies("1.2.3+build.123", "1.2.3")
        assert satisfies("1.2.3+build1", "1.2.3+build2")

    @pytest.mark.parametrize(
        "version,range_spec",
        [
            ("1.2.3", "=1.2.3"),
            ("0.0.0", "=0.0.0"),
            ("10.20.30", "=10.20.30"),
        ],
    )
    def test_explicit_equal_operator(self, version, range_spec):
        assert satisfies(version, range_spec)


class TestGreaterThan:
    """Test > operator."""

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("1.2.4", ">1.2.3", True),
            ("2.0.0", ">1.2.3", True),
            ("1.2.3", ">1.2.3", False),
            ("1.2.2", ">1.2.3", False),
            ("1.0.0", ">1", True),
            ("2.0.0", ">1", True),
            ("1.0.0", ">1", True),
            ("0.9.9", ">1", False),
        ],
    )
    def test_greater_than(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    def test_greater_than_with_whitespace(self):
        assert satisfies("1.2.4", "> 1.2.3")


class TestGreaterThanOrEqual:
    """Test >= operator."""

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("1.2.4", ">=1.2.3", True),
            ("1.2.3", ">=1.2.3", True),
            ("1.2.2", ">=1.2.3", False),
            ("1.2.0", ">=1.2", True),
        ],
    )
    def test_greater_than_or_equal(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    def test_greater_than_or_equal_with_whitespace(self):
        assert satisfies("1.2.3", ">= 1.2.3")


