class TestXRanges:
    """Test x, X, and * in ranges."""

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("0.0.0", "*", True),
            ("1.2.3", "*", True),
            ("99.99.99", "*", True),
            ("0.0.0", "x", True),
            ("1.2.3", "X", True),
            ("0.0.0", "", True),
            ("5.6.7", "", True),
        ],
    )
    def test_match_any(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("1.0.0", "1.x", True),
            ("1.5.0", "1.X", True),
            ("1.99.99", "1", True),
            ("1.0.0", "1", True),
            ("2.0.0", "1.x", False),
            ("0.99.99", "1.x", False),
        ],
    )
    def test_major_only_matches_in_major(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("1.2.0", "1.2.x", True),
            ("1.2.5", "1.2.X", True),
            ("1.2.99", "1.2", True),
            ("1.2.0", "1.2", True),
            ("1.3.0", "1.2.x", False),
            ("1.2.0-alpha", "1.2.x", False),
        ],
    )
    def test_major_minor_matches_in_patch(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("2.0.0", ">1", True),
            ("1.5.0", ">1", True),
            ("1.0.0", ">1", False),
        ],
    )
    def test_greater_than_x_range(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("1.0.0", "<2", True),
            ("1.5.0", "<2", True),
            ("2.0.0", "<2", False),
        ],
    )
    def test_less_than_x_range(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("1.0.0", ">1.2", True),
            ("1.3.0", ">1.2", True),
            ("1.2.0", ">1.2", False),
        ],
    )
    def test_greater_than_partial_version(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("1.2.0", "<1.2", False),
            ("1.1.9", "<1.2", True),
        ],
    )
    def test_less_than_partial_version(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("1.2.0", ">=1.2", True),
            ("1.3.0", ">=1.2", True),
            ("1.1.9", ">=1.2", False),
        ],
    )
    def test_greater_equal_partial_version(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("1.1.9", "<=1.2", True),
            ("1.2.0", "<=1.2", False),
            ("1.0.0", "<=1.2", True),
        ],
    )
    def test_less_equal_partial_version(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected


class TestTildeRanges:
    """Test tilde (~) ranges."""

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("1.2.3", "~1.2.3", True),
            ("1.2.4", "~1.2.3", True),
            ("1.2.99", "~1.2.3", True),
            ("1.3.0", "~1.2.3", False),
            ("2.0.0", "~1.2.3", False),
            ("1.2.2", "~1.2.3", False),
        ],
    )
    def test_tilde_with_full_version(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("1.2.0", "~1.2", True),
            ("1.2.5", "~1.2", True),
            ("1.3.0", "~1.2", False),
        ],
    )
    def test_tilde_with_major_minor(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("1.0.0", "~1", True),
            ("1.5.0", "~1", True),
            ("2.0.0", "~1", False),
        ],
    )
    def test_tilde_with_major_only(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("0.2.3", "~0.2.3", True),
            ("0.2.4", "~0.2.3", True),
            ("0.3.0", "~0.2.3", False),
        ],
    )
    def test_tilde_with_zero_major(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    def test_tilde_with_prerelease(self):
        assert satisfies("1.2.3-beta.2", "~1.2.3-beta.2")
        assert satisfies("1.2.3", "~1.2.3-beta.2")
        assert not satisfies("1.3.0", "~1.2.3-beta.2")


class TestCaretRanges:
    """Test caret (^) ranges."""

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("1.2.3", "^1.2.3", True),
            ("1.5.0", "^1.2.3", True),
            ("1.99.99", "^1.2.3", True),
            ("2.0.0", "^1.2.3", False),
            ("1.2.2", "^1.2.3", False),
        ],
    )
    def test_caret_with_nonzero_major(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("0.2.3", "^0.2.3", True),
            ("0.2.4", "^0.2.3", True),
            ("0.3.0", "^0.2.3", False),
            ("0.2.2", "^0.2.3", False),
        ],
    )
    def test_caret_with_zero_major(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("0.0.3", "^0.0.3", True),
            ("0.0.4", "^0.0.3", False),
            ("0.0.3", "^0.0.3", True),
        ],
    )
    def test_caret_with_zero_major_minor(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    def test_caret_with_prerelease_nonzero_major(self):
        assert satisfies("1.2.3-beta.2", "^1.2.3-beta.2")
        assert satisfies("1.5.0", "^1.2.3-beta.2")
        assert not satisfies("2.0.0", "^1.2.3-beta.2")

    def test_caret_with_prerelease_zero_major(self):
        assert satisfies("0.0.3-beta", "^0.0.3-beta")
        assert not satisfies("0.0.4", "^0.0.3-beta")

    @pytest.mark.parametrize(
