        [
            ("1.2.0", "^1.2", True),
            ("1.5.0", "^1.2", True),
            ("2.0.0", "^1.2", False),
        ],
    )
    def test_caret_with_partial_minor(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("1.0.0", "^1.x", True),
            ("1.5.0", "^1.x", True),
            ("2.0.0", "^1.x", False),
        ],
    )
    def test_caret_with_x_minor(self, version, range_spec, expected):
        assert satisfies(version, range_spec) == expected

    @pytest.mark.parametrize(
        "version,range_spec,expected",
        [
            ("1.0.0", "^1", True),
            ("1.5.0", "^1", True),
            ("2.0.0", "^1", False),
        ],
    )
    def test_caret_with_major_only(self, version, range_spec, expected):
