            ("1.2.3+build.123", ">1.2.2"),
            ("1.2.3+build.123", "^1.2.0"),
        ],
    )
    def test_build_metadata_ignored(self, version, range_spec):
        assert satisfies(version, range_spec)


class TestEdgeCases:
    """Test edge cases and corner cases."""

    def test_zero_versions(self):
        assert satisfies("0.0.0", "0.0.0")
        assert satisfies("0.0.1", ">=0.0.0")

    def test_large_version_numbers(self):
        assert satisfies("999.999.999", "999.999.999")

    def test_many_prerelease_identifiers(self):
        assert satisfies("1.0.0-alpha.1.2.3.4.5", "1.0.0")

    def test_complex_prerelease_identifiers(self):
        assert satisfies("1.0.0-x-y-z-123", "1.0.0")

    def test_empty_range(self):
        assert satisfies("1.2.3", "")

    def test_whitespace_variations(self):
        assert satisfies("v  1.2.3", "1.2.3")
        assert satisfies("1.2.3", "v  1.2.3  ")

    def test_multiple_spaces_between_comparators(self):
        assert satisfies("1.5.0", ">=1.0.0   <2.0.0")

    def test_prerelease_in_x_range(self):
